const MAX_BYTES = 1_000_000;
const GENERATED_MARKERS = [
  "@generated",
  "do not edit",
  "auto-generated",
  "autogenerated",
  "this file was generated",
  "code generated",
];

export type ContentProblem = "binary" | "lfs_pointer" | "non_utf8" | "too_large" | "generated_or_vendored";

export interface Inspected {
  problem?: ContentProblem;
  text?: string;
}

/** Decides whether file content can be analyzed as text; returns the decoded text when it can. */
export function inspectContent(buffer: Buffer, checkGenerated: boolean): Inspected {
  if (buffer.length > MAX_BYTES) return { problem: "too_large" };
  const head = buffer.subarray(0, 8000);
  if (head.includes(0)) return { problem: "binary" };
  if (head.subarray(0, 64).toString("latin1").startsWith("version https://git-lfs.github.com/spec")) {
    return { problem: "lfs_pointer" };
  }
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: false }).decode(buffer);
  } catch {
    return { problem: "non_utf8" };
  }
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  if (checkGenerated && hasGeneratedHeader(text)) return { problem: "generated_or_vendored" };
  return { text };
}

const COMMENT_LEADERS = ["//", "/*", "*", "#", "--", "<!--"];

/** A generated-file marker counts only inside a comment line near the top of the file. */
function hasGeneratedHeader(text: string): boolean {
  const head = text.slice(0, 2048).split(/\r?\n/, 15);
  return head.some((line) => {
    const t = line.trim().toLowerCase();
    return COMMENT_LEADERS.some((c) => t.startsWith(c)) && GENERATED_MARKERS.some((m) => t.includes(m));
  });
}
